// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testing.
type Clock interface {
	Now() time.Time
}

// Limiter is a token-bucket rate limiter. Tokens refill continuously at rate
// tokens per second, up to a burst capacity. The zero value is not usable;
// construct with New.
type Limiter struct {
	mu       sync.Mutex
	burst    float64 // bucket capacity
	rate     float64 // tokens per second
	tokens   float64 // current tokens
	lastRef  time.Time
	clock    Clock
}

// New creates a Limiter allowing rate events per second with burst capacity.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be > 0")
	}
	if burst <= 0 {
		return nil, errors.New("ratelimit: burst must be > 0")
	}
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	return &Limiter{
		burst:   float64(burst),
		rate:    rate,
		tokens:  float64(burst),
		lastRef: clock.Now(),
		clock:   clock,
	}, nil
}

// AllowN reports whether n events may happen now.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.lastRef).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.lastRef = now
	}

	need := float64(n)
	if need > l.tokens {
		return false
	}
	l.tokens -= need
	return true
}

// Allow reports whether a single event may happen now.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// Tokens returns the current number of available tokens (for diagnostics).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	elapsed := l.clock.Now().Sub(l.lastRef).Seconds()
	t := l.tokens + elapsed*l.rate
	if t > l.burst {
		t = l.burst
	}
	return t
}
