	defer c.mu.Unlock()
	return c.now
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.now = c.now.Add(d)
}

func TestNewValidation(t *testing.T) {
	clock := newFakeClock(time.Unix(0, 0))
	tests := []struct {
		name    string
		rate    float64
		burst   int
		clock   Clock
		wantErr bool
	}{
		{"ok", 1, 1, clock, false},
		{"zero rate", 0, 1, clock, true},
		{"negative rate", -1, 1, clock, true},
		{"zero burst", 1, 0, clock, true},
		{"negative burst", 1, -1, clock, true},
		{"nil clock", 1, 1, nil, true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			_, err := New(tc.rate, tc.burst, tc.clock)
			if (err != nil) != tc.wantErr {
				t.Fatalf("New() error = %v, wantErr %v", err, tc.wantErr)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	base := time.Unix(0, 0)
	tests := []struct {
		name      string
		rate      float64
		burst     int
		steps     []struct {
			advance time.Duration
			n       int
			want    bool
		}
	}{
		{
			name: "burst exhausted then refill",
			rate: 1, burst: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},   // consume full burst
				{0, 1, false},  // empty
				{time.Second, 1, true},  // one token refilled
				{0, 1, false},
				{time.Second, 2, true},  // back to full burst
			},
		},
		{
			name: "no time means no refill",
			rate: 100, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{0, 1, false},
				{0, 1, false},
			},
		},
		{
			name: "fractional refill accumulates",
			rate: 2, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{200 * time.Millisecond, 1, false}, // 0.4 tokens
				{200 * time.Millisecond, 1, true},  // 0.8 tokens
				{0, 1, false},
			},
		},
		{
			name: "negative n denied",
			rate: 1, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, -1, false},
				{0, 1, true},
			},
		},
		{
			name: "large request never partially consumed",
			rate: 1, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 5, false},
				{0, 1, true},
			},
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			clock := newFakeClock(base)
			lim, err := New(tc.rate, tc.burst, clock)
			if err != nil {
				t.Fatalf("New() error = %v", err)
			}
			for i, s := range tc.steps {
				clock.Advance(s.advance)
				if got := lim.AllowN(s.n); got != s.want {
					t.Fatalf("step %d: AllowN(%d) = %v, want %v", i, s.n, got, s.want)
				}
			}
		})
	}
}

func TestConcurrentAllow(t *testing.T) {
	clock := newFakeClock(time.Unix(0, 0))
	lim, err := New(1000, 100, clock)
	if err != nil {
		t.Fatalf("New() error = %v", err)
	}
	const goroutines = 50
	var wg sync.WaitGroup
	var mu sync.Mutex
	allowed := 0
	for i := 0; i < goroutines; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if lim.Allow() {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if allowed != 100 {
		t.Fatalf("allowed = %d, want 100 (burst)", allowed)
	}
}
